import{_ as a,o as i,c as s,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Alchemy","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/alchemy.md","filePath":"es/game-design/professions/alchemy.md"}'),n={name:"es/game-design/professions/alchemy.md"};function r(l,e,t,c,d,p){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="alchemy" tabindex="-1">Alchemy <a class="header-anchor" href="#alchemy" aria-label="Enlace permanente a &quot;Alchemy&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; todas las mecánicas, ejemplos y vías de técnicas siguientes siguen siendo candidatos. <strong>Implementación:</strong> este batch documental no establece implementación de este rediseño. <strong>Disponibilidad:</strong> no establecida. <strong>Verificación:</strong> solo revisión documental; sin prueba de gameplay. <strong>Revisado:</strong> 2026-10-09 para la proyección pública; estado del diseño y mecánicas conservados de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/alchemy.html">Panorama para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Propósito y ciclo profesional <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Enlace permanente a &quot;Propósito y ciclo profesional&quot;">​</a></h2><p>Alchemy debería basarse en procesos simplificados de química temprana/alquimia, sin convertirse en un simulador de química.</p><h3 id="core-operations" tabindex="-1">Operaciones principales <a class="header-anchor" href="#core-operations" aria-label="Enlace permanente a &quot;Operaciones principales&quot;">​</a></h3><ul><li>Triturar</li><li>Disolver</li><li>Calentar</li><li>Destilar</li><li>Separar</li><li>Combinar</li></ul><p>Los materiales contienen principios/esencias descubribles como:</p><ul><li>Motive</li><li>Vital</li><li>Volatile</li><li>Combustive</li><li>Toxic</li><li>Somnolent</li><li>Purifying</li><li>etc.</li></ul><p>Los nombres exactos siguen en el nivel de diseño y pueden permanecer en estado Propuesto.</p><p>El sistema debería enfatizar principios/reacciones, no solo recetas fijas de pociones.</p><p>Ejemplo: Combustive + Volatile -&gt; comportamiento explosivo. Vital + Restorative -&gt; preparado regenerativo. Toxic + Penetrating -&gt; preparado de tipo venenoso.</p><h3 id="laboratory-equipment" tabindex="-1">Equipo de laboratorio <a class="header-anchor" href="#laboratory-equipment" aria-label="Enlace permanente a &quot;Equipo de laboratorio&quot;">​</a></h3><ul><li>mortero y mano;</li><li>vial;</li><li>quemador;</li><li>crisol;</li><li>alambique/retorta/condensador;</li><li>balanzas;</li><li>recipientes de reacción.</li></ul><h3 id="relevant-variables" tabindex="-1">Variables pertinentes <a class="header-anchor" href="#relevant-variables" aria-label="Enlace permanente a &quot;Variables pertinentes&quot;">​</a></h3><ul><li>medio de extracción/disolvente;</li><li>estado térmico;</li><li>pureza;</li><li>concentración;</li><li>estabilidad.</li></ul><p>No exponer en exceso cifras químicas exactas a los jugadores salvo justificación posterior.</p><h3 id="products" tabindex="-1">Productos <a class="header-anchor" href="#products" aria-label="Enlace permanente a &quot;Productos&quot;">​</a></h3><ul><li>brebajes;</li><li>aceites;</li><li>polvos;</li><li>pastas;</li><li>ungüentos;</li><li>toxinas;</li><li>disolventes;</li><li>reactivos;</li><li>mezclas volátiles;</li><li>tintas;</li><li>conservantes.</li></ul><h3 id="pvp-and-pvm-utility" tabindex="-1">Utilidad en PvP y PvM <a class="header-anchor" href="#pvp-and-pvm-utility" aria-label="Enlace permanente a &quot;Utilidad en PvP y PvM&quot;">​</a></h3><ul><li>mezclas explosivas;</li><li>humo;</li><li>irritantes;</li><li>adhesivos;</li><li>preparados temporizados/diferidos;</li><li>venenos;</li><li>apoyo médico.</li></ul><h3 id="localized-injury-interactions" tabindex="-1">Interacciones con lesiones localizadas <a class="header-anchor" href="#localized-injury-interactions" aria-label="Enlace permanente a &quot;Interacciones con lesiones localizadas&quot;">​</a></h3><ul><li>el coagulante reduce el sangrado;</li><li>el analgésico reduce temporalmente penalizaciones por dolor sin curar trauma;</li><li>el estimulante afecta a la fatiga;</li><li>los antídotos interactúan con principios de toxinas.</li></ul><p>El veneno debería llegar a ser más rico que Poison 1–5 fijo. Variables posibles:</p><ul><li>toxicidad;</li><li>aparición;</li><li>duración/persistencia;</li><li>administración;</li><li>familias de síntomas.</li></ul><p>La experimentación debería generar observaciones y nuevas formulaciones.</p><h2 id="knowledge-and-specialization" tabindex="-1">Conocimiento y especialización <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Enlace permanente a &quot;Conocimiento y especialización&quot;">​</a></h2><p><strong>Alchemical Journal.</strong> Distillation y Toxicology son ejemplos de técnicas aprendidas; observaciones y reacciones llevan a formulaciones, no solo a ventanas de recetas. Nombres y ejemplos de reacciones siguen siendo provisionales.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Progresión, producción y economía compartidas <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Enlace permanente a &quot;Progresión, producción y economía compartidas&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> define enseñanza y dirección de límite/progreso. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, conocimiento compartido, dominio manual, producción por lotes, encargos y reputación multidimensional. Esas reglas no se redefinen aquí de forma independiente. La <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación de calidad</a> define los límites compartidos de resultados y las propiedades raras de objetos.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Habilidades relacionadas e interacciones en el terreno <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Enlace permanente a &quot;Habilidades relacionadas e interacciones en el terreno&quot;">​</a></h2><p>Alchemy puede suministrar cargas de Tinkering, tratamientos/tintes de Tailoring, tratamientos de Carpentry y preparados médicos. Healing, trauma local, fatiga y Concentration mágica requieren diseño coordinado en vez de efectos inferidos.</p><p><a href="/Syrolands-Public/es/game-design/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/es/game-design/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/es/game-design/combat/damage.html">Local Trauma</a> · <a href="/Syrolands-Public/es/game-design/combat/future-directions.html">Futuros sistemas de lesiones</a> · <a href="/Syrolands-Public/es/game-design/magic.html#meditation-and-concentration">Meditation y Concentration</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Conservar solo estado e información que apoyen decisiones significativas. Se aplican las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de abstracción/autoridad</a> y la arquitectura del mundo vivo; la persistencia requiere un diseño técnico separado. Aquí no se eligen identificadores de paquetes, esquemas, temporizadores, recursos de interfaz ni algoritmos de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Taxonomía de esencias y reglas de reacción; intervalos de extracción; información cualitativa; estabilidad y almacenamiento; administración, dosis, acumulación, respuestas posibles y fuego amigo; aparición/duración/síntomas de toxinas; compatibilidad con Healing y lesiones. Los ejemplos siguientes no establecen rediseño de sangrado, dolor ni veneno en la parte actual.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro compartido de conciliación</a> define los conflictos entre sistemas. Los experimentos y la evidencia de combate existentes no validan este rediseño de profesiones.</p><h2 id="magic-materials-—-batch-04" tabindex="-1">Materiales mágicos — Batch 04 <a class="header-anchor" href="#magic-materials-—-batch-04" aria-label="Enlace permanente a &quot;Materiales mágicos — Batch 04&quot;">​</a></h2><p>Los <a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html#reagents-remain-physical-resources">reactivos</a> siguen siendo catalizadores, estabilizadores, portadores y componentes físicos, generalmente saqueables. Alchemy puede prepararlos/procesarlos para Core Patterns, modificadores e <a href="/Syrolands-Public/es/game-design/professions/inscription.html">Inscription</a>. Esto está en estado Propuesto: no hay familia de reactivos, fórmula de sustitución, dependencia de producción ni cambio de objeto en ejecución definitivos.</p>',40)])])}const h=a(n,[["render",r]]);export{u as __pageData,h as default};
